import{_ as t,o as l,c as s,a2 as a}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Supermarket","description":"","frontmatter":{},"headers":[],"relativePath":"guides/supermarket.md","filePath":"guides/supermarket.md","lastUpdated":1781675678000}'),i={name:"guides/supermarket.md"};function n(r,e,o,u,p,d){return l(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="supermarket" tabindex="-1">Supermarket <a class="header-anchor" href="#supermarket" aria-label="Permalink to &quot;Supermarket&quot;">​</a></h1><p>Supermarket is Memoh&#39;s built-in catalog for <strong>plugins</strong> and <strong>skills</strong>. In v0.13, plugins are the recommended way to install bundled MCP resources, skills, hooks, auth requirements, and setup scripts together.</p><p>The Web UI shows Supermarket under Settings with two tabs:</p><ul><li><strong>Plugins</strong></li><li><strong>Skills</strong></li></ul><hr><h2 id="install-a-plugin" tabindex="-1">Install A Plugin <a class="header-anchor" href="#install-a-plugin" aria-label="Permalink to &quot;Install A Plugin&quot;">​</a></h2><ol><li>Open <strong>Supermarket</strong> in the Web UI.</li><li>Switch to the <strong>Plugins</strong> tab.</li><li>Choose a plugin and click <strong>Install</strong>, or open the plugin detail page and click <strong>Install to Bot</strong>.</li><li>Select the target bot.</li><li>Fill in any required variables shown by the plugin manifest.</li><li>Confirm the install.</li><li>If the plugin returns <code>needs_auth</code>, complete the OAuth popup.</li><li>Memoh opens the target bot&#39;s <strong>Plugins</strong> tab.</li></ol><p>During installation, Memoh fetches the plugin manifest, downloads the trusted Supermarket bundle when available, extracts plugin assets, runs manifest <code>install</code> commands, and creates the bot-scoped plugin installation.</p><p>Plugin detail pages show the plugin&#39;s MCP resources, bundled skills, auth type, author, version, schema version, and links.</p><hr><h2 id="install-a-skill" tabindex="-1">Install A Skill <a class="header-anchor" href="#install-a-skill" aria-label="Permalink to &quot;Install A Skill&quot;">​</a></h2><ol><li>Open <strong>Supermarket</strong> in the Web UI.</li><li>Switch to the <strong>Skills</strong> tab.</li><li>Choose a skill and click <strong>Install</strong>, or open the skill detail page and click <strong>Install to Bot</strong>.</li><li>Select the target bot.</li><li>Confirm the install.</li><li>The skill appears in that bot&#39;s <strong>Skills</strong> tab.</li></ol><p>Standalone skills install into the bot&#39;s managed skills directory. Plugin-provided skills are installed through plugin bundles instead.</p><hr><h2 id="configure-supermarket" tabindex="-1">Configure Supermarket <a class="header-anchor" href="#configure-supermarket" aria-label="Permalink to &quot;Configure Supermarket&quot;">​</a></h2><p>By default, Memoh reads Supermarket content from:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">supermarket</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://supermarket.memoh.ai&quot;</span></span></code></pre></div><p>Operators can point <code>supermarket.base_url</code> at another trusted catalog. The configured endpoint is used for plugin manifests, plugin bundle downloads, skill lists, skill details, and skill downloads.</p><hr><h2 id="plugin-bundle-contents" tabindex="-1">Plugin Bundle Contents <a class="header-anchor" href="#plugin-bundle-contents" aria-label="Permalink to &quot;Plugin Bundle Contents&quot;">​</a></h2><p>A trusted plugin bundle may provide:</p><ul><li><code>skills/</code>: skill files discovered as plugin-provided skills.</li><li><code>hooks.json</code>: plugin hooks loaded only from enabled, ready plugin installations.</li><li><code>scripts/</code>: helper scripts used by manifest <code>install</code> commands.</li></ul><p>Bundle files are extracted under <code>/data/.memoh/plugins/&lt;plugin_id&gt;</code> inside the target bot workspace. The archive path checker ignores unsupported entries and rejects unsafe paths.</p><hr><h2 id="contribute" tabindex="-1">Contribute <a class="header-anchor" href="#contribute" aria-label="Permalink to &quot;Contribute&quot;">​</a></h2><p>Contribute new plugins or skills here:</p><ul><li><a href="https://github.com/memohai/supermarket" target="_blank" rel="noreferrer">memohai/supermarket</a></li></ul>`,27)])])}const c=t(i,[["render",n]]);export{g as __pageData,c as default};
